\label{main}
If the initial datum $\omega_{0}\in L^\infty$ has compact support, there exists a solution $\omega\in L^{1}([0,T], L^\infty)$ of \eqref{cauchysystem}
for every $T>0$.

\label{LinftyK}
Let $f:\mathbb C\to\mathbb C$ be given, and assume $f\in L^\infty$. 
\begin{itemize}
\item[(a)] If $f\in L^{1}$, then $K\ast f\in L^\infty$ and 
\begin{equation}\label{without support}
\|K\ast f\|_\infty\leq C\,\|f\|_1^{\frac12}\,\|f\|_\infty^{\frac12},
\end{equation} 
\item[(b)] If $f$ has compact support, then
\begin{equation}\label{with support}
\|K\ast f\|_\infty\leq C\,|\operatorname{supp} f|^{\frac12}\,\|f\|_\infty.
\end{equation}
\item[(c)] If $f$ is compactly supported, then 
$$\limsup_{|x|\to\infty} |x|\,|K\ast f(x)|\leq C<+\infty$$
with $C$ depending only on $\|f\|_\infty$ and $|\operatorname{supp}(f)|$. 
\end{itemize}

\label{qcflows}
Let $T>0$ be fixed. Then: 
\begin{itemize}
\item[(a)] $X^\epsilon(t,\cdot)$ is $\mathcal{K}_t$-quasiconformal, with $1\leq\mathcal{K}_t\leq e^{|t|\|\omega_0\|_\infty}$, where $-T\leq t\leq T$.
\item[(b)] There exists a constant $C=C(\mathcal{K}_t)$ such that
$$
\frac1C\left(\frac{|z-z_0|}{|z-w_0|}\right)^{\mathcal{K}_t}\leq\frac{|X^\epsilon(t,z)-X^\epsilon(t,z_0)|}{|X^\epsilon(t,z)-X^\epsilon(t,w_0)|}\leq C\left(\frac{|z-z_0|}{|z-w_0|}\right)^\frac1{\mathcal{K}_t}
$$
for any $z,z_0,w_0\in\mathbb C$ and any time $t\in[-T,T]$. 
\item[(c)] There exists a constant $C=C(\mathcal{K}_t)$ such that  
$$\frac{|X^\epsilon(t,E)|}{|X^\epsilon(t,D)|}\leq C(\mathcal{K}_t)\,\left(\frac{|E|}{|D|}\right)^\frac1{\mathcal{K}_t}.$$
whenever $D\subset\mathbb C$ is a disk and $E\subset D$ is measurable.
\end{itemize}

\label{compactness}
Assume that $X^\epsilon(t,\cdot)$ is uniformly bounded on compact sets. Then:
\begin{enumerate}
\item[(a)] $\{X^\epsilon(t,\cdot)\}_\epsilon$ is pointwise equicontinuous.
\item[(b)] $\{X^\epsilon(t,\cdot)\}_\epsilon$ accumulates to a $\mathcal{K}_t$-quasiconformal map $X(t,\cdot)$.
\end{enumerate}

\label{principal}
Let $X^\epsilon(t,\cdot)$ be as before, and assume that $\omega_0$ has compact support.
\begin{itemize}
\item[(a)] For each $t,\epsilon$ there exists $b^\epsilon(t)\in\mathbb C$ such that $\lim_{|z|\to\infty}|X^\epsilon(t,z)-z-b^\epsilon(t)|=0.$
\item[(b)] One has $|X^\epsilon(t,E)|\leq \mathcal{K}_t\,|E|$ for each set $E\supset \operatorname{supp}\omega_0^\epsilon$.
\end{itemize}

\label{normstability}
Assume that $K(z)=\frac{e^{i\theta}}{2\pi z}$. If $\omega_0$ is compactly supported, then 
\begin{itemize}
\item[(a)] $\|\omega^\epsilon(t,\cdot)\|_\infty\leq \|\omega_0\|_\infty$


\item[(b)] $\|\omega^\epsilon(t,\cdot)\|_1\leq \|\omega _0\|_\infty\,e^{t\|\omega_0\|_\infty}\,|\operatorname{supp}\omega^\epsilon_0|$.
\item[(c)] $\|\mathbf{v}^\epsilon(t,\cdot)\|_\infty\leq C(K) \,e^{\frac{t}2\,\|\omega_0\|_\infty}\,\|\omega_0\|_\infty\,|\operatorname{supp}\omega_0^\epsilon|^\frac12$.
\end{itemize}

\label{equivform}
The scalar-valued function $\omega:[0,T]\times\mathbb C\to\mathbb R$ is a weak solution of
\begin{equation}\label{omegaequation}
\begin{cases} \omega_t+\mathbf{v}\cdot\nabla\omega=0\\\mathbf{v}=K\ast\omega \\\omega|_{t=0}=\omega_0\end{cases}
\end{equation}
if and only if $\mathbf{v}:[0,T]\times\mathbb C\to\mathbb C$ and $q:[0,T]\times\mathbb C\to\mathbb R$ solve
\begin{equation}\label{vequation}
\begin{cases}\mathbf{v}_t+\mathbf{v}\cdot\nabla\mathbf{v} = -\mathbf M_\theta\nabla q\\
-\Delta q = \operatorname{div}(\mathbf{v})\,\operatorname{div}(\mathbf M_\theta\mathbf{v})\\
\operatorname{curl}(\mathbf M_\theta\mathbf{v})|_{t=0}=0\\
\operatorname{div}(\mathbf M_\theta\mathbf{v})|_{t=0}=\omega_0
\end{cases}
\end{equation}
also in the weak sense.
